--
-- Disparadores `ordenes_compras`
--
DELIMITER $$
CREATE TRIGGER `tr_ordenes_compras_auditoria` BEFORE UPDATE ON `ordenes_compras` FOR EACH ROW BEGIN
    -- Insertar registro en la tabla de auditoría con hora de Caracas (UTC-4)
        id_orden,
        tasa_dia_anterior, tasa_dia_nuevo,
        totalGeneral_anterior, totalGeneral_nuevo,
        totalbs_anterior, totalbs_nuevo,
        iva_anterior, iva_nuevo,
        fecha_edicion,
        usuario_edicion
    ) VALUES (
        OLD.id,
        OLD.tasa_dia, NEW.tasa_dia,
        OLD.totalGeneral, NEW.totalGeneral,
        OLD.totalbs, NEW.totalbs,
        OLD.iva, NEW.iva,
        -- Usar CONVERT_TZ para obtener la hora de Caracas (UTC-4)
        CONVERT_TZ(NOW(), 'SYSTEM', '-04:00'),
        -- Obtener el usuario actual de MySQL
        CURRENT_USER()
    );
END
$$
DELIMITER ;

